package com.example.crm.auth;
import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class AuthService {final UserRepository users;final RefreshTokenRepository tokens;final PasswordEncoder encoder;final JwtService jwt; public AuthService(UserRepository u,RefreshTokenRepository t,PasswordEncoder e,JwtService j){users=u;tokens=t;encoder=e;jwt=j;} public Map<String,Object> login(String name,String pass){var u=users.findByUsername(name).filter(x->x.isEnabled()&&encoder.matches(pass,x.getPasswordHash())).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));return issue(u);} public Map<String,Object> refresh(String raw){var t=tokens.findByTokenAndRevokedFalse(raw).filter(x->x.getExpiresAt().isAfter(Instant.now())).orElseThrow(()->new IllegalArgumentException("Invalid refresh token"));t.setRevoked(true);tokens.save(t);return issue(t.getUser());} public void logout(String raw){tokens.findByTokenAndRevokedFalse(raw).ifPresent(t->{t.setRevoked(true);tokens.save(t);});} private Map<String,Object> issue(UserAccount u){String r=UUID.randomUUID().toString();tokens.save(new RefreshToken(r,u,Instant.now().plus(Duration.ofDays(30))));return Map.of("accessToken",jwt.create(u),"refreshToken",r,"tokenType","Bearer","expiresIn",jwt.ttl(),"user",Map.of("username",u.getUsername(),"role",u.getRole().name()));} }
